require dirname(__DIR__).'/bootstrap.php';method('GET');$ann=one('SELECT subject,message FROM '.table('forum_announcement').' WHERE starttime<=? AND (endtime=0 OR endtime>?) AND type=0 ORDER BY displayorder,id DESC LIMIT 1',[time(),time()]);$file=__DIR__.'/release.json';$version=is_file($file)?json_decode(file_get_contents($file),true):['latest'=>'1.0.0','minimum'=>'1.0.0','force_update'=>false,'download_url'=>null];respond(['app_name'=>'ZO论坛','api_version'=>1,'site_url'=>'https://www.zozse.cn','version'=>$version,'features'=>['public_browsing'=>true,'posting'=>true,'sms'=>true,'lottery'=>true,'gamebox'=>true,'ai_search'=>true],'announcement'=>$ann?['enabled'=>true,'title'=>$ann['subject'],'content_html'=>clean_html($ann['message'])]:['enabled'=>false]]);
